{
  "analysis": {
    "requires_lua": false,
    "requires_workflow": true,
    "requires_network": true,
    "requires_filesystem": false,
    "requires_side_effects": true,
    "domain": "crypto",
    "suggested_name": "crypto.monitor_btc_price",
    "summary": "Monitor BTC price four times daily for seven days (28 checks) and notify via Telegram when price is above 100000 USD, using chained monitor batches because total iterations exceed 20."
  },
  "workflow": {
    "definition": {
      "format": "semantic_plan",
      "plan": {
        "version": "workflow-plan-v1",
        "name": "monitor_btc_4x_daily_7d",
        "steps": [
          {
            "kind": "repeat",
            "id": "monitor_batch",
            "steps": [
              {
                "kind": "call",
                "id": "fetch_price",
                "capability_name": "market.coin_price",
                "args": {
                  "symbol": "btc",
                  "currency": "usd"
                }
              },
              {
                "kind": "call",
                "id": "tick",
                "capability_name": "stat.tick",
                "args": {
                  "iteration": {
                    "ref": "tick",
                    "path": "iteration"
                  },
                  "state": {
                    "ref": "tick",
                    "path": "state"
                  },
                  "initial_state": {
                    "ref": "payload",
                    "path": "continuation.state"
                  }
                }
              },
              {
                "kind": "condition",
                "when": {
                  "greater": [
                    {
                      "var": "fetch_price.price"
                    },
                    100000
                  ]
                },
                "steps": [
                  {
                    "kind": "call",
                    "id": "compose_alert",
                    "capability_name": "llm.evaluate",
                    "args": {
                      "task": "Compare o preço atual com o anterior (se houver) e escreva uma mensagem de notificação em português explicando que o preço do BTC ultrapassou 100000 USD, incluindo o preço atual e a variação de 24h. Retorne decision como 'notify' ou 'skip' e a mensagem em 'message'.",
                      "current": {
                        "price": {
                          "ref": "fetch_price",
                          "path": "price"
                        },
                        "change_24h": {
                          "ref": "fetch_price",
                          "path": "change_24h"
                        },
                        "timestamp": {
                          "ref": "fetch_price",
                          "path": "timestamp"
                        }
                      },
                      "previous": {
                        "ref": "payload",
                        "path": "continuation.previous_snapshot"
                      }
                    }
                  },
                  {
                    "kind": "condition",
                    "when": {
                      "==": [
                        {
                          "var": "compose_alert.decision"
                        },
                        "notify"
                      ]
                    },
                    "steps": [
                      {
                        "kind": "call",
                        "id": "send_telegram",
                        "capability_name": "telegram.send",
                        "args": {
                          "text": {
                            "ref": "compose_alert",
                            "path": "message"
                          }
                        }
                      }
                    ],
                    "otherwise": []
                  }
                ],
                "otherwise": []
              }
            ],
            "interval_seconds": 21600.0,
            "count": 20,
            "state": {
              "tick": {
                "ref": "tick",
                "path": "state"
              }
            }
          },
          {
            "kind": "call",
            "id": "advance_chain",
            "capability_name": "stat.chain_step",
            "args": {
              "iteration": {
                "ref": "tick",
                "path": "iteration"
              },
              "remaining_iterations": {
                "ref": "payload",
                "path": "continuation.remaining_iterations"
              },
              "initial_remaining": {
                "ref": "payload",
                "path": "continuation.initial_remaining"
              },
              "state": {
                "ref": "tick",
                "path": "state"
              },
              "previous_state": {
                "ref": "payload",
                "path": "continuation.state"
              }
            }
          }
        ]
      }
    },
    "name": "monitor_btc_4x_daily_7d",
    "description": "Monitor Bitcoin price 4 times per day (every 6 hours) for 7 days (28 total checks). Because the requested 28 iterations is greater than the 20-iteration single-chain cap, this workflow runs a batch of 20 checks (one batch) and calls stat.chain_step to record progress and enable a continuation that will perform the remaining 8 checks. On any check where price > 100000 USD, it asks llm.evaluate to decide and compose a Portuguese notification; if llm.evaluate returns decision 'notify' the workflow sends the composed message to Telegram.",
    "required_capabilities": [
      "market.coin_price",
      "llm.evaluate",
      "telegram.send",
      "stat.tick",
      "stat.chain_step"
    ]
  }
}

