  "script": {
    "format": "luau_body",
    "helpers": "local function c_to_f(c: number): number\n    -- Convert Celsius to Fahrenheit using the formula F = C * 9/5 + 32\n    return c * 9 / 5 + 32\nend\n",
    "body": "function run(input: Input, context: Context): Output\n    -- Expect input.celsius to be present (per schema)\n    local c: number = input.celsius\n    local f: number = c_to_f(c)\n    return { fahrenheit = f }\nend"
  },
  "name": "convert_celsius_to_fahrenheit",
  "description": "Convert a temperature from Celsius to Fahrenheit.",
  "usage_description": "Use this when you need to transform a Celsius temperature into Fahrenheit.",
  "tags": [
    "temperature",
    "conversion"
  ],
  "risk_assessment": "low",
  "runtime_profile": "transform_only"
}

