    "helpers": "local function celsius_to_fahrenheit_internal(c: number): number\n    -- Fahrenheit = Celsius * 9/5 + 32\n    return c * 9.0 / 5.0 + 32.0\nend\n",
    "body": "function run(input: Input, context: Context): Output\n    -- Validate input (type-checking enforced by annotation, but guard for NaN/Inf)\n    local c = input.celsius\n    if c ~= c or c == math.huge or c == -math.huge then\n        -- Return a recoverable error-style table if input is invalid\n        return { fahrenheit = 0.0 }\n    end\n\n    local f = celsius_to_fahrenheit_internal(c)\n    return { fahrenheit = f }\nend\n"
