      "format": "luau_body",
      "helpers": "local function buildMessage(name: string): string\n\treturn \"Hi \" .. name .. \", we miss you!\"\nend\n",
      "body": "function run(input: Input, context: Context): Output\n\tlocal listed = tools.crm.list({ segment = input.segment })\n\tif listed.error then\n\t\treturn { error = listed.error, message = listed.message }\n\tend\n\n\tlocal notified: { string } = {}\n\tlocal failed: { string } = {}\n\tlocal sent = 0\n\tfor _, customer in listed.customers do\n\t\tif customer.last_seen_days >= input.inactive_days then\n\t\t\tif sent >= 10 then\n\t\t\t\tbreak\n\t\t\tend\n\t\t\tlocal response = tools.message.send({ user = customer.id, text = buildMessage(customer.name) })\n\t\t\tif response.error then\n\t\t\t\ttable.insert(failed, customer.id)\n\t\t\telse\n\t\t\t\ttable.insert(notified, customer.id)\n\t\t\t\tsent += 1\n\t\t\tend\n\t\tend\n\tend\n\n\treturn { notified = notified, failed = failed, count = #notified }\nend"
    },
